import React from "react";
import FadeIn from "react-fade-in";
import './style.css';
import $ from 'jquery'; 
import NumberFormat from 'react-number-format';
import { useLocation } from "react-router-dom";

const Depositar = () => {
    
    let location = useLocation();
    if (location.pathname == "/depositar") {
        const depositar = () => {
            $.post("http://m_bank/depositar",JSON.stringify({
                amount: Number($("#valDeposito").val())
            }))
        }
        let carteira: any = localStorage.getItem("carteira")
        carteira = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(carteira)
        return (
            <div className="content-depositar">
                <FadeIn>
                    <div className="content">
                        <div className="quantia">
                            <label htmlFor="">Dinheiro na carteira: <br />{carteira}</label>
                            <label htmlFor="">Quantia Depositada</label>
                            <NumberFormat allowNegative={false} id="valDeposito" placeholder="R$ 300,00"/>
                        </div>
                        <div className="button">
                            <button onClick={depositar}>Depositar</button>
                        </div>
                    </div>
                </FadeIn>
            </div>
        )
    } else {
        return(<div></div>)
    }
}

export default Depositar;