import React from "react";
import FadeIn from "react-fade-in";
import './style.css';
import $ from 'jquery'; 
import NumberFormat from 'react-number-format';

const Pix = () => {
    const pix = () => {
        $.post("http://m_bank/pix",JSON.stringify({
            pixTo: $("#pixTo").val(),
            amount: Number($("#valTransfer").val()),
        }))
    }
    return (
        <div className="content-pix">
            <FadeIn>
                <div className="content">
                    <div className="passaporte">
                        <label htmlFor="">Chave Pix</label>
                        <input id="pixTo" type="text" placeholder="PIX" />
                    </div>
                    <div className="quantia">
                        <label htmlFor="">Quantia</label>
                        <NumberFormat allowNegative={false} id="valTransfer" placeholder="R$ 300,00"/>
                    </div>
                    <div className="button">
                        <button onClick={pix}>PIX</button>
                    </div>
                </div>
            </FadeIn>
        </div>
    )
}

export default Pix;