import React, { useCallback, useState, useContext, createContext} from 'react';
import './App.css'
import { useNuiEvent } from "../../hooks/useNuiEvent";
import { useExitListener } from "../../hooks/useExitListener";
import Sidebar from './components/sidebar'
import Dashboard from './pages/Dashboard';
import routes from '../../routes';
import { Route } from 'react-router-dom';
import FadeIn from 'react-fade-in';
import {fetchNui} from "../../utils/fetchNui";
export let qualquer = React.createContext([])

const App: React.FC = () => {
  const [isVisible, setIsVisible] = useState(false)
 
  useNuiEvent<boolean>('setVisible', (data) => {
    setIsVisible(data)
  })

  if (window.location.href != "nui://m_bank/web/build/index.html#/") {
    window.location.href = "nui://m_bank/web/build/index.html#/"
  }

  useExitListener(setIsVisible)

  let img:any = localStorage.getItem('bankImg')
  let nome:any = localStorage.getItem('bankName')

  return (
    <FadeIn>
        <div className='container' style={{ visibility: isVisible ? 'visible' : 'hidden' }}>
            <Sidebar image={img} name={nome} />
            <div className="tablet">
                {routes.map((object: any, idx: React.Key) => (
                  <Route key={idx} path={object.path} exact={object.exact} render={(props: any) => (
                    <object.component {...props} />
                  )}></Route>
                ))}
            </div>
        </div>
    </FadeIn>
  );
}

export default App;