import React from "react";
import FadeIn from "react-fade-in";
import './style.css';
import $ from 'jquery'; 
import NumberFormat from 'react-number-format';

const Sacar = () => {
    const sacar = () => {
        $.post("http://m_bank/sacar",JSON.stringify({
            amount: Number($("#valSaque").val())
        }))
    }
    return (
        <div className="content-sacar">
            <FadeIn>
            <div className="content">
                <div className="quantia">
                    <label htmlFor="">Quantia</label>
                    <NumberFormat allowNegative={false} id="valSaque" placeholder="R$ 300,00"/>
                </div>
                <div className="button">
                    <button onClick={sacar}>Sacar</button>
                </div>
            </div>
            </FadeIn>
        </div>
    )
}

export default Sacar;