import React from 'react';
import { AiFillHome, AiOutlineUserSwitch, AiOutlineHome, AiOutlineArrowUp, AiOutlineArrowDown } from 'react-icons/ai'
import { BiTransfer } from 'react-icons/bi'
import './style.css'
import { Link } from 'react-router-dom';
import FadeIn from "react-fade-in";

interface SidebarProps {
    image: string;
    name: string;
}

const Sidebar = ({ image, name }: SidebarProps) => {
    return (
        <div className="sidebar">
            <div className="content">
                <FadeIn>
                    <div className="top-sidebar">
                        <img src={image} alt="" />
                        <h1>{name}</h1>
                    </div>
                    <div className="sidebar-btns">
                        <div className="sidebar-btn">
                            <Link to='/'><span><AiFillHome /> Home</span></Link>
                            <Link to='/depositar'><span><AiOutlineArrowDown /> Depositar</span></Link>
                            <Link to='/sacar'><span><AiOutlineArrowUp /> Sacar</span></Link>
                            <Link to='/transferir'><span><BiTransfer /> Transferir</span></Link>
                            <Link to='/pix'><span><AiOutlineUserSwitch /> Pix</span></Link>
                            <Link to='/multas'><span><AiOutlineUserSwitch /> Pagar Multas</span></Link>
                        </div>
                    </div>
                </FadeIn>
            </div>
        </div >
    )
}

export default Sidebar;