import React from "react";
import FadeIn from "react-fade-in";
import './style.css';
import $ from 'jquery'; 
import NumberFormat from 'react-number-format';

const Transferir = () => {
    const transferir = () => {
        $.post("http://m_bank/transferir",JSON.stringify({
            transferTo: Number($("#transferTo").val()),
            amount: Number($("#valTransfer").val()),
        }))
    }
    return (
        <div className="content-transferir">
            <FadeIn>
                <div className="content">
                    <div className="passaporte">
                        <label htmlFor="">Passaporte</label>
                        <input id="transferTo" type="number" placeholder="1" />
                    </div>
                    <div className="quantia">
                        <label htmlFor="">Quantia</label>
                        <NumberFormat allowNegative={false} id="valTransfer" placeholder="R$ 300,00"/>
                    </div>
                    <div className="button">
                        <button onClick={transferir}>Transferir</button>
                    </div>
                </div>
            </FadeIn>
        </div>
    )
}

export default Transferir;