import React from 'react';
import Dashboard from './pages/Home/pages/Dashboard';
import Depositar from './pages/Home/pages/Depositar';
import Sacar from './pages/Home/pages/Sacar';
import Transferir from './pages/Home/pages/Transferir';
import Pix from './pages/Home/pages/Pix';
import Multas from './pages/Home/pages/Multas';

const routes = [
  { path: '/', exact: true, component: Dashboard },
  { path: '/transferir', exact: true, component: Transferir },
  { path: '/sacar', exact: true, component: Sacar },
  { path: '/depositar', exact: true, component: Depositar },
  { path: '/pix', exact: true, component: Pix },
  { path: '/multas', exact: true, component: Multas },
];

export default routes;
