import React from "react";
import FadeIn from "react-fade-in";
import './style.css';
import $ from 'jquery'; 
import NumberFormat from 'react-number-format';

const Multas = () => {
    const multas = () => {
        $.post("http://m_bank/multas",JSON.stringify({
            amount: Number($("#valSaque").val())
        }))
    }
    let banco2:any = localStorage.getItem('banco')
    banco2 = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(banco2)
    let qtdMultas: any = localStorage.getItem("multas")
    qtdMultas = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(qtdMultas)
    return (
        <div className="content-multas">
            <FadeIn>
            <div className="content">
                <div className="quantia">
                    <label htmlFor="">Multas: {qtdMultas}</label>
                    <label htmlFor="">Saldo no banco: {banco2}</label>
                    <label htmlFor="">Quantia paga:</label>
                    <NumberFormat allowNegative={false} id="valSaque" placeholder="R$ 300,00"/>
                </div>
                <div className="button">
                    <button onClick={multas}>Pagar</button>
                </div>
            </div>
            </FadeIn>
        </div>
    )
}

export default Multas;