import React, { useState } from "react";
import { AiOutlineShopping, AiOutlineBank } from 'react-icons/ai'
import './style.css'
import FadeIn from "react-fade-in";
import { useNuiEvent } from "../../../../hooks/useNuiEvent";
import image from '../../../../assets/mastercard.png'
import ReactApexChart from "react-apexcharts";
import { ApexOptions } from 'apexcharts';
import $ from 'jquery';
import Modal from 'react-modal';


let renderizado = 0
const Dashboard = (props : any) => {
    const [modalIsOpen, setIsOpen] = React.useState(false);
    const [modalIsOpen2, setIsOpen2] = React.useState(false);

    function openModal() {
        setIsOpen(true);
    }
    
    function closeModal() {
        setIsOpen(false);
    }
    
    function openModal2() {
        setIsOpen2(true);
    }
    
    function closeModal2() {
        setIsOpen2(false);
    }

    let pix2:any = localStorage.getItem('pix')
    let name2:any = localStorage.getItem('name')
    let id2:any = localStorage.getItem('id')
    let graph2:any = localStorage.getItem('graph')
    let banco2:any = localStorage.getItem('banco')
    let transacoes2:any = localStorage.getItem('transacoes')  
    let bankName:any = localStorage.getItem('bankName')
    let bankImg:any = localStorage.getItem('bankImg')
    
    useNuiEvent('setDashboardInformation',(data) => {
        renderizado = 1
        
        localStorage.clear()
        localStorage.setItem('bankName',data[0])
        localStorage.setItem('bankImg',data[1])
        localStorage.setItem('banco',JSON.stringify(data[2]))
        localStorage.setItem('transacoes',JSON.stringify(data[3]))
        localStorage.setItem('graph',JSON.stringify(data[4]))
        localStorage.setItem('pix',data[6])
        localStorage.setItem('name',data[5])
        localStorage.setItem('id',JSON.stringify(data[7]))
        localStorage.setItem('carteira',JSON.stringify(data[11]))
        localStorage.setItem('multas',JSON.stringify(data[12]))
    })

    if (renderizado == 1) {
        
        transacoes2 = JSON.parse(transacoes2)
        graph2 = JSON.parse(graph2)
        
        const cadastrarPix = () => {
            $.post("http://m_bank/cadastrarPix",JSON.stringify({
                value: $("#criarPix").val(),
            }))
            setIsOpen(false);
        }
        
        const editarPix = () => {
            $.post("http://m_bank/editarPix",JSON.stringify({
                value: $("#editarPix").val(),
            }))
            setIsOpen2(false);
        }

        const options: ApexOptions = {
            chart: {
                toolbar: {
                    show: false,
                },
                zoom: {
                    enabled: false,
                },
                foreColor: "#131313",
            },
            labels: [
                'Ganhos',
                'Percas',
                'Multas'
            ],
            colors:['#33cc95', '#e52e4d', '#5429cc'],
            grid: {
                show: false,
            },
            dataLabels: {
                enabled: false,
            },
            tooltip: {
                enabled: false,
            },
            xaxis: {
                type: 'datetime',
                axisBorder: {
                    color: "#131313",
                },
                axisTicks: {
                    color: "#131313",
                },
                categories: [
                    '2021-06-23T00:00:00.000Z',
                    '2021-06-24T00:00:00.000Z',
                    '2021-06-25T00:00:00.000Z',
                    '2021-06-26T00:00:00.000Z',
                    '2021-06-27T00:00:00.000Z',
                    '2021-06-28T00:00:00.000Z',
                    '2021-06-29T00:00:00.000Z',
                ],
            },

            fill: {
                opacity: 0.3,

                type: 'gradient',
                gradient: {
                    shade: 'dark',
                    opacityFrom: 0.7
                },
            }
        };

        class Loop extends React.Component {
            renderRow(row: any){
                return (
                    <div className="transaction">
                        <div className="left">
                            <div className="icon">
                                {transacoes2[row].store == "Loja" ? <AiOutlineShopping /> : null }
                                {transacoes2[row].store == "Banco" ? <AiOutlineBank /> : null}
                            </div>
                            <div className="text">
                                <h1>{transacoes2[row].store}</h1>
                                <span>{transacoes2[row].tipo}</span>
                            </div>
                        </div>
                        <div className="right">
                            <h1>{new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(transacoes2[row].valor)}</h1>
                        </div>
                    </div>
                )
            }
            render(){
                let rows = []
                
                for(let i=0; i<transacoes2.length; i++){
                    rows.push(i)
                }
                if (rows.length == 0) {
                    return <p>Sem movimentações</p>
                  }
                return (
                    <div> 
                        {rows.map(this.renderRow)}
                    </div>
                )
            } 
        }

        return (
            <div className="content-dashboard">
                <div className="content">
                    <FadeIn>
                        <div className="left">
                            <div className="visao-geral">
                            <h1 className="title">Olá, <strong>{name2}</strong></h1>

                                <div className="first">
                                    <h1>Saldo total:</h1>
                                    <span>{new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(banco2)}</span>
                                </div>
                                <div className="second">
                                    <h2>Número da conta:</h2>
                                    <span>{id2}</span>
                                </div>
                            </div>
                            <div className="card-area">
                                <h1>Meu cartão</h1>
                                <div className="card">
                                    <div className="top">
                                        <img src={image} alt="" />

                                    </div>
                                    <div className="center">
                                        <h2>5234 1234 4321 3212</h2>
                                    </div>
                                    <div className="bottom">
                                        <h1>{name2}</h1>
                                        <h2>02/24</h2>
                                        <h3>316</h3>
                                    </div>
                                </div>
                            </div>
                            <div className="transactions-area">
                                <h1>Movimentação recentes</h1>
                                <Loop />
                            </div>
                            <div className="saldo">
                                <div className="graph">
                                    <h1>Gráfico de suas movimentações</h1>
                                    <ReactApexChart series={graph2} options={options} className="graph-donut" type="donut" width={350} height={300} />
                                </div>
                            </div>
                            <div className="pix">
                                <h1>PIX</h1>
                                <p>Faça transferências facilmente!</p>
                                <div className="buttons">
                                    {pix2 == 'null' ? <button onClick={openModal}>Criar</button> : <button onClick={openModal} disabled>Criar</button>}
                                    {pix2 == 'null' ? <button onClick={openModal2} disabled>Editar</button> : <button onClick={openModal2} >Editar</button>}
                                </div>

                                <div className="codigo">
                                    <label htmlFor="">Seu código PIX:</label>
                                    <input type="text" placeholder={pix2 == 'null' ? 'CRIE SEU PIX' : pix2} disabled />
                                </div>
                            </div>
                        </div>

                        <Modal isOpen={modalIsOpen} onRequestClose={closeModal} className="pix-modal">
                            <div className="pix-container">
                                <h1>Criar um PIX</h1>
                                <label htmlFor="">Cadastre já seu pix</label>
                                <input id="criarPix" type="text" placeholder="SEU PIX" />
                                <button onClick={cadastrarPix}>Criar</button>
                            </div>
                        </Modal>
                        <Modal isOpen={modalIsOpen2} onRequestClose={closeModal2} className="pix-modal">
                            <div className="pix-container">
                                <h1>Editar um PIX</h1>
                                <label htmlFor="">Cadastre já seu pix</label>
                                <input id="editarPix" type="text" placeholder="SEU PIX" />
                                <button onClick={editarPix}>Editar</button>
                            </div>
                        </Modal>
                    </FadeIn>
                </div>
            </div>
        )
    } else{
        return(<div></div>);
    }
}

export default Dashboard;